INSERT INTO profession_details (profession_id, reality, pros, cons) VALUES
(98, 'Не "просветитель душ". Это 50% дисциплины (садись, тихо!), 30% бумаг, и 20% "а вдруг кто-то поймёт?". И родители: почему двойка?', '["Влияешь на будущее — реально", "Стабильность — дети всегда будут", "Каникулы (если не бумаги)", "Уважение в обществе"]', '["50% дисциплины, не обучение", "Зарплата — смешная", "Бумаги больше уроков", "Родители кричат", "Выгорание через 5-7 лет"]'),
(99, 'Не "волшебник". Это 50% слушания (молча), 30% "а что если?", и 20% собственной терапии (чтобы не сойти с ума).', '["Помогаешь людям — реально", "Глубокие разговоры — работа", "Можно работать из дома", "Нет потолка дохода (частная практика)"]', '["50% слушания молча", "Клиенты не делают домашку", "Эмоциональное выгорание", "Своя терапия — обязательна", "Конкуренция огромная"]'),
(100, 'Не "корпоративный психолог". Это 50% отказов (не подошли), 30% бумаг, и 20% "а вдруг уйдёт?".', '["Работа с людьми — каждый день", "Влияешь на культуру компании", "Стабильность — HR всегда нужен", "Можно работать в любой сфере"]', '["50% отказов", "Кандидаты не приходят", "Бумаги больше людей", "Конфликты (увольнения)", "Выгорание через 5 лет"]'),
(101, 'Не "ангел в белом". Это 12-часовые смены, ночные дежурства, смерть, которую ты не спас. И родители: вы убили нашего ребёнка.', '["Спасаешь жизни — реально", "Уважение в обществе", "Стабильность — люди болеют всегда", "Можно уехать в любую страну"]', '["12-часовые смены", "Смерть — часть работы", "Родители кричат", "Бумаги больше лечения", "Выгорание через 5 лет"]'),
(102, 'Не "святой". Это 50% бюрократии (отчёты, заявления), 30% трагедий (помогите, нас выселяют), и 20% спасибо (редкость).', '["Помогаешь людям — реально", "Глубокие разговоры — работа", "Можно изменить жизнь", "Смысл — каждый день"]', '["50% бюрократии", "Трагедии каждый день", "Выгорание через 3 года", "Зарплата — смешная", "Бюджет сокращают"]'),
(103, 'Не "волшебник речи". Это 70% повторения одного звука, 20% "родитель знает лучше", и 10% "он сказал мама!".', '["Помогаешь детям — смысл", "Виден результат — через месяцы", "Эмпатия + терпение = мастерство", "Можно свой кабинет"]', '["70% повторения", "Родители знают лучше", "Результат — через месяцы", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(104, 'Не "массаж в спа". Это 60% физического труда, 30% "а вдруг не поможет?", и 10% "наконец-то пошевелил пальцем!".', '["Помогаешь людям — реально", "Виден результат — через недели", "Можно свой кабинет", "Эмпатия + анатомия = мастерство"]', '["60% физического труда", "Руки устают", "Клиенты в панике", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(105, 'Не "звезда Instagram". Это 70% "а вдруг похудею?", 20% планов питания, и 10% "наконец-то влезла в платье!".', '["Помогаешь людям — реально", "Здоровье — смысл", "Можно свой кабинет", "Наука + эмпатия = мастерство"]', '["70% а вдруг похудею?", "Клиенты не слушают", "Результат — через месяцы", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(106, 'Не "спа-уход". Это 80% физического труда, 15% "а вдруг больно?", и 5% "наконец-то расслабился!".', '["Помогаешь людям — реально", "Тактильность = доверие", "Можно свой кабинет", "Виден результат — сразу"]', '["80% физического труда", "Руки устают", "Клиенты в панике", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(107, 'Не "хранитель мудрости". Это 70% каталогизации, 20% поиска (где этот документ?), и 10% чтения. И тишина — иногда гнетёт.', '["Тишина — порядок", "Каждый день понятный", "Можно читать (иногда)", "Стабильность — всегда нужны"]', '["70% каталогизации", "Тишина гнетёт", "Зарплата — смешная", "Никто не ценит", "Выгорание через 5 лет"]'),
(108, 'Не "проповедник". Это 60% приходских дел, 30% "а вдруг потерял веру?", и 10% "наконец-то покой в душе".', '["Помогаешь людям — смысл", "Глубокие разговоры — работа", "Уважение в обществе", "Стабильность — всегда нужны"]', '["60% приходских дел", "Вера — не работа", "Зарплата — смешная", "Конфликты в приходе", "Выгорание через 5 лет"]'),
(109, 'Не "защитник правды". Это 50% медиации (давайте договоримся), 30% бумаг, и 20% "наконец-то развелись!".', '["Помогаешь людям — реально", "Мир — лучше войны", "Можно свой кабинет", "Эмпатия + логика = мастерство"]', '["50% медиации", "Клиенты в ярости", "Бумаги больше людей", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(110, 'Не "разоблачитель". Это 70% "источник не хочет говорить", 20% "редактор вырезал", и 10% "вот оно — правда!".', '["Правда — валюта", "Влияешь на общество", "Можно изменить мир", "Каждый день новое"]', '["70% источники молчат", "Редактор вырезает", "Опасность — угрозы", "Зарплата низкая", "Выгорание через 5 лет"]'),
(111, 'Не "эксперт по ТВ". Это 60% анализа данных, 30% "а вдруг не угадал?", и 10% "вот оно — прогноз сбылся!".', '["Аналитика + влияние", "Виден результат — выборы", "Можно в университет", "Каждый цикл — новое"]', '["60% данных", "Ошибка = позор", "Бумаги больше анализа", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(112, 'Не "пиарщик". Это 50% кризисов (всё пропало!), 30% текстов, и 20% "наконец-то репутация спасена!".', '["Слово — валюта", "Влияешь на мнение", "Можно в любую сферу", "Каждый день новое"]', '["50% кризисов", "Всё пропало — норма", "Босс не понимает", "Зарплата на старте низкая", "Выгорание через 3 года"]'),
(113, 'Не "звезда спорта". Это 60% мотивации (ещё раз!), 30% травм, и 10% "наконец-то медаль!".', '["Помогаешь расти — смысл", "Виден результат — через месяцы", "Можно свой зал", "Энергия каждый день"]', '["60% мотивации", "Клиенты ленятся", "Травмы — норма", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(114, 'Не "путешествие каждый день". Это 70% "а вдруг дождь?", 20% "где туалет?", и 10% "вот этот вид!".', '["Показываешь мир", "Общение каждый день", "Можно работать везде", "Каждый тур — новое"]', '["70% погода", "Туалет — вопрос", "Голос садится", "Зарплата на старте низкая", "Сезонность"]'),
(115, 'Не "полиглот из фильма". Это 80% терминологии, 15% "а вдруг не точно?", и 5% "вот оно — идеальный перевод!".', '["Языки — власть", "Можно работать везде", "Каждый проект — новое", "Удалёнка — норма"]', '["80% терминология", "Точность — стресс", "Замена ИИ", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(116, 'Не "миротворец". Это 50% "оба неправы", 30% "а вдруг не получится?", и 20% "наконец-то рукопожатие!".', '["Мир — лучше войны", "Помогаешь людям — реально", "Можно свой кабинет", "Эмпатия + нейтралитет = мастерство"]', '["50% оба неправы", "Клиенты в ярости", "Результат не гарантирован", "Зарплата на старте низкая", "Выгорание через 5 лет"]'),
(117, 'Не "учитель 2.0". Это 60% платформ, 30% "а вдруг не зашёл?", и 10% "наконец-то понял!".', '["Помогаешь расти — смысл", "Масштаб — тысячи учеников", "Можно работать из дома", "Каждый курс — новое"]', '["60% платформа", "Ученики не заходят", "Техника ломается", "Зарплата на старте низкая", "Выгорание через 3 года"]'),
(118, 'Не "учитель 2.0". Это 60% платформ, 30% "а вдруг не зашёл?", и 10% "наконец-то понял!".', '["Помогаешь расти — смысл", "Масштаб — тысячи учеников", "Можно работать из дома", "Каждый курс — новое"]', '["60% платформа", "Ученики не заходят", "Техника ломается", "Зарплата на старте низкая", "Выгорание через 3 года"]'),
(119, 'Не "пиарщик". Это 50% кризисов (всё пропало!), 30% текстов, и 20% "наконец-то репутация спасена!".', '["Слово — валюта", "Влияешь на мнение", "Можно в любую сферу", "Каждый день новое"]', '["50% кризисов", "Всё пропало — норма", "Босс не понимает", "Зарплата на старте низкая", "Выгорание через 3 года"]');
